  box-shadow: var(--inlay-shadow);
  transition: box-shadow 0.3s ease;
}
.regex-script-label.flex-container:hover,
.flex-container .script-item:hover {
  box-shadow:
    inset 0 2px 5px rgba(255, 227, 77, 0.25),
    inset 0 -2px 5px rgba(0, 0, 0, 0.5),
    0 0 0 1.5px var(--pk),
    0 0 0 3.5px var(--inlay-dark),
    0 0 0 4.5px rgba(255, 126, 179, 0.4),
    0 0 18px rgba(255, 126, 179, 0.12);
}
.regex-script-label.flex-container .regex_script_name,
.script-item .script-item-name {
