  color: #FFE0F0;
}
.regex-script-label.flex-container > .flex-container.flexnowrap,
.script-item .script-item-control { width: 100%; justify-content: flex-start; }

/* ══════════════════════════════════════════════
   十一、加载更多消息
   ══════════════════════════════════════════════ */
#show_more_messages {
  font-size: 0 !important; color: transparent !important;
  display: block; padding: 10px 28px;
  margin: 20px auto; width: fit-content;
  background: linear-gradient(135deg, rgba(12, 8, 16, 0.9), rgba(18, 10, 14, 0.85));
  border: none;
  border-radius: 25px;
  box-shadow:
    inset 0 2px 4px rgba(255, 227, 77, 0.12),
    inset 0 -2px 4px rgba(0, 0, 0, 0.45),
    0 0 0 1.5px rgba(255, 194, 212, 0.3),
    0 0 0 3.5px rgba(6, 3, 8, 0.75),
    0 0 0 4.5px rgba(255, 227, 77, 0.18),
    0 0 14px rgba(255, 126, 179, 0.06);
