/* ══════════════════════════════════════════════
   十二、思维链
   ══════════════════════════════════════════════ */
.mes_reasoning_summary {
  list-style: none; cursor: pointer;
  display: flex !important; align-items: center;
}
.mes_reasoning_header {
  background: linear-gradient(135deg, rgba(18, 10, 22, 0.85), rgba(22, 12, 18, 0.7));
