/* ══════════════════════════════════════════════
   ★★★★★ 十七、小剧场模板自治 ★★★★★

   ══════════════════════════════════════════════ */

/* ───── 1️⃣ details 内一切元素 → 回归角色卡原生设计 ───── */
.mes .mes_text details,
.mes .mes_text details *:not(summary):not(summary *) {
  color: revert !important;
  -webkit-text-fill-color: revert !important;
  text-shadow: none !important;
  filter: none !important;
  font-weight: revert !important;
  font-style: revert !important;
  letter-spacing: normal !important;
}

/* ───── 2️⃣ details 内不继承我们的背景/边框/光晕 ───── */
.mes .mes_text details p,
.mes .mes_text details strong,
.mes .mes_text details b,
.mes .mes_text details em,
.mes .mes_text details i,
.mes .mes_text details blockquote,
.mes .mes_text details ul,
.mes .mes_text details ol,
.mes .mes_text details li,
.mes .mes_text details h1,
.mes .mes_text details h2,
.mes .mes_text details h3,
.mes .mes_text details h4,
.mes .mes_text details h5,
.mes .mes_text details h6,
.mes .mes_text details hr,
.mes .mes_text details code,
.mes .mes_text details q {
  background: none !important;
  background-color: transparent !important;
  background-image: none !important;
  border: none !important;
  border-image: none !important;
  border-left: none !important;
  border-right: none !important;
  border-bottom: none !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  padding: revert !important;
  margin: revert !important;
}

/* ───── 3️⃣ 去掉 details 内 q/blockquote/hr 的伪元素装饰 ───── */
.mes .mes_text details q::before,
.mes .mes_text details q::after,
.mes .mes_text details blockquote::before,
.mes .mes_text details blockquote::after,
.mes .mes_text details hr::before,
.mes .mes_text details hr::after {
  content: none !important;
  display: none !important;
}

/* ───── 4️⃣ summary 标题保留月光粉色 ───── */
.mes .mes_text summary,
.mes .mes_text details > summary {
  color: #FFB8CC !important;
  -webkit-text-fill-color: #FFB8CC !important;
  text-shadow: 0 0 6px rgba(255, 126, 179, 0.3) !important;
  background: none !important;
  border: none !important;
}
.mes .mes_text summary [style*="color"] {
  color: inherit !important;
  -webkit-text-fill-color: inherit !important;
}

/* ══════════════════════════════════════════════
   ★ 5️⃣ 暗红色 — 转为月光暖金 ★

   ══════════════════════════════════════════════ */

/* 命名色 */
.mes .mes_text [style*="darkred" i],
.mes .mes_text [style*="crimson" i],
.mes .mes_text [style*="firebrick" i],
.mes .mes_text [style*="maroon" i],
.mes .mes_text [style*="indianred" i],
.mes .mes_text [style*="brown" i],
.mes .mes_text [style*="sienna" i],
/* HEX 暗红色家族 */
.mes .mes_text [style*="#8B0000" i],
.mes .mes_text [style*="#800000" i],
.mes .mes_text [style*="#A52A2A" i],
.mes .mes_text [style*="#B22222" i],
.mes .mes_text [style*="#8B1A1A" i],
.mes .mes_text [style*="#7A0000" i],
.mes .mes_text [style*="#6B0000" i],
.mes .mes_text [style*="#4A0000" i],
.mes .mes_text [style*="#5C0000" i],
.mes .mes_text [style*="#3D0000" i],
.mes .mes_text [style*="#2A0000" i],
.mes .mes_text [style*="#990000" i],
.mes .mes_text [style*="#660000" i],
.mes .mes_text [style*="#cc0000" i],
.mes .mes_text [style*="#c0392b" i],
.mes .mes_text [style*="#a93226" i],
.mes .mes_text [style*="#922b21" i] {
  color: #FFD27A !important;
  -webkit-text-fill-color: #FFD27A !important;
  text-shadow:
    0 1px 2px rgba(0, 0, 0, 0.85),
    0 0 8px rgba(255, 200, 100, 0.35) !important;
}

/* 暗红色边框 → 改为柔金边框（让那些方框可见） */
.mes .mes_text [style*="border-color: darkred" i],
.mes .mes_text [style*="border-color:darkred" i],
.mes .mes_text [style*="border: 1px solid darkred" i],
.mes .mes_text [style*="border:1px solid darkred" i],
.mes .mes_text [style*="border-color: #8B0000" i],
.mes .mes_text [style*="border-color:#8B0000" i],
.mes .mes_text [style*="border-color: #800000" i],
.mes .mes_text [style*="border-color:#800000" i],
.mes .mes_text [style*="border-color: maroon" i],
.mes .mes_text [style*="border-color:maroon" i],
.mes .mes_text [style*="border-color: crimson" i],
.mes .mes_text [style*="border-color:crimson" i] {
  border-color: rgba(255, 200, 100, 0.65) !important;
  box-shadow:
    0 0 0 1px rgba(8, 4, 12, 0.5),
    0 0 10px rgba(255, 200, 100, 0.18) !important;
}

/* 兜底：任何 details 里的标题（h1~h6 / strong / b）若为暗色 → 强制亮起来 */
.mes .mes_text details h1,
.mes .mes_text details h2,
.mes .mes_text details h3,
.mes .mes_text details h4,
.mes .mes_text details h5,
.mes .mes_text details h6 {
  color: #FFE0A8 !important;
  -webkit-text-fill-color: #FFE0A8 !important;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.85), 0 0 10px rgba(255, 200, 100, 0.3) !important;
}

/* 兜底：details 内段落正文如果太暗（被原卡设成深色），保底亮度 */
.mes .mes_text details p,
.mes .mes_text details span:not([style*="color"]),
.mes .mes_text details div:not([style*="color"]) {
  color: #F0DCC0 !important;
  -webkit-text-fill-color: #F0DCC0 !important;
}
